grid=[[0,8,8,0,8,8,0],[8,8,8,8,8,8,0],[0,8,8,0,8,0,0],[0,0,8,8,8,0,0]]
cells={(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==8}
# all connected triomino L placements
placements=[]
for r in range(4):
 for c in range(6):
  for miss in [(0,0),(0,1),(1,0),(1,1)]:
   ss={(r+dr,c+dc) for dr in range(2) for dc in range(2) if (dr,dc)!=miss}
   if ss<=cells: placements.append(('L',miss,ss))
for r in range(3):
 for c in range(6):
  ss={(r+i,c+j) for i in range(2) for j in range(2)}
  if ss<=cells: placements.append(('S',None,ss))
# exact covers by recursive smallest uncovered cell
sol=[]
def rec(rem, chosen):
 if not rem:
  sol.append(chosen); return
 x=min(rem)
 for p in placements:
  ss=p[2]
  if x in ss and ss<=rem:
   rec(rem-ss,chosen+[p])
rec(cells,[])
len(cells),len(sol),[(sum(p[0]=='S' for p in s),sum(p[0]=='L' for p in s)) for s in sol[:10]]
